window.__votdWeek && window.__votdWeek({"week":"2029-07-23","reading":"Doctrine and Covenants 81–83","days":[{"d":"2029-07-23","ref":"D&C 81:4","b":"D&C","c":81,"v":4,"he":"וּבַעֲשׂוֹתְךָ אֶת־הַדְּבָרִים הָאֵלֶּה תַּעֲשֶׂה אֶת־הַטּוֹב הַגָּדוֹל לִבְנֵי אָדָם וּתְגַדֵּל אֶת־כְּבוֹד אֲדֹנֶיךָ׃","en":"And in doing these things thou wilt do the greatest good unto thy fellow beings, and wilt promote the glory of him who is your Lord."},{"d":"2029-07-24","ref":"D&C 81:5","b":"D&C","c":81,"v":5,"he":"לָכֵן הֱיֵה נֶאֱמָן עֲמֹד בַּמִּשְׂרָה אֲשֶׁר מִנִּיתִיךָ בָּהּ סְעַד אֶת־הַחַלָּשִׁים הָרֵם יָדַיִם רָפוֹת וְחַזֵּק בִּרְכַּיִם כֹּשְׁלוֹת׃","en":"Wherefore, be faithful; stand in the office which I have appointed unto you; succor the weak, lift up the hands which hang down, and strengthen the feeble knees."},{"d":"2029-07-25","ref":"D&C 81:6","b":"D&C","c":81,"v":6,"he":"וְאִם נֶאֱמָן אַתָּה עַד הַקֵּץ יִהְיֶה־לְּךָ כֶּתֶר אַל־מָוֶת וְחַיֵּי עוֹלָם בַּמְּעוֹנוֹת אֲשֶׁר הֲכִינֹתִי בְּבֵית אָבִי׃","en":"And if thou art faithful unto the end thou shalt have a crown of immortality, and eternal life in the mansions which I have prepared in the house of my Father."},{"d":"2029-07-26","ref":"D&C 82:3","b":"D&C","c":82,"v":3,"he":"כִּי מֵאֲשֶׁר נִתַּן לוֹ הַרְבֵּה הַרְבֵּה נִדְרָשׁ מִמֶּנּוּ וְהַחוֹטֵא נֶגֶד הָאוֹר הַגָּדוֹל יְקַבֵּל מִשְׁפָּט גָּדוֹל יוֹתֵר׃","en":"For of him unto whom much is given much is required; and he who sins against the greater light shall receive the greater condemnation."},{"d":"2029-07-27","ref":"D&C 82:6","b":"D&C","c":82,"v":6,"he":"וְאַף אֱלֹהִים בֹּעֵר בְּיוֹשְׁבֵי הָאָרֶץ וְאֵין עֹשֶׂה טוֹב כִּי כֻלָּם סָרוּ מִן הַדֶּרֶךְ׃","en":"And the anger of God kindleth against the inhabitants of the earth; and none doeth good, for all have gone out of the way."},{"d":"2029-07-28","ref":"D&C 82:10","b":"D&C","c":82,"v":10,"he":"אֲנִי יְהוָה עָרֵב כַּאֲשֶׁר אַתֶּם עוֹשִׂים אֶת־אֲשֶׁר אֲנִי אֹמֵר אַךְ כַּאֲשֶׁר אֵינְכֶם עוֹשִׂים אֶת־אֲשֶׁר אֲנִי אֹמֵר אֵין לָכֶם הַבְטָחָה׃","en":"I, the Lord, am bound when ye do what I say; but when ye do not what I say, ye have no promise."},{"d":"2029-07-29","ref":"D&C 83:6","b":"D&C","c":83,"v":6,"he":"וְהָאוֹצָר יִשָּׁמֵר בִּתְרוּמוֹת הַכְּנֵסִיָּה וְהָאַלְמָנוֹת וְהַיְתוֹמִים יְכֻלְכְּלוּ וְכֵן גַּם הָעֲנִיִּים אָמֵן׃","en":"And the storehouse shall be kept by the consecrations of the church; and widows and orphans shall be provided for, as also the poor. Amen."}]});
